#include <assert.h>
#include <stddef.h>
struct Stack { int data[3]; size_t count; };
int push(struct Stack *s, int value) {
 if (s == NULL || s->count == 3) return 0;
 s->data[s->count++] = value; return 1;
}
int main(void) {
 struct Stack s = {{0}, 0};
 assert(push(&s, 7));
 assert(s.count == 1 && s.data[0] == 7);
 return 0;
}
